sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float3x3 acLayerToScreen;
uniform float time;
uniform float phase;
uniform float angle;
uniform float spacing;
uniform float magnitude;
uniform float warpAngle;
uniform float damping;
uniform float dampingSpace;
uniform float dampingOrigin;
uniform float screenSpace;
uniform float speed;
float2 AcLayerNorm(float2 p) {
    float3 h = toLayer * float3(p, 1.0);
    return h.xy / max(layer, float2(1.0));
}
half4 main(float2 coord) {
    float a1 = radians(angle);
    float a2 = radians(angle + warpAngle);
    float2 st = screenSpace > 0.5 ? (coord - screen.xy) / max(screen.zw, float2(1.0)) : AcLayerNorm(coord);

    float2 rawV = float2(cos(a1), -sin(a1));
    float rawP = dot(st, rawV);
    float spaceDamp = 1.0;
    if (dampingSpace < 0.0) {
        spaceDamp = 1.0 - clamp(abs(rawP - dampingOrigin), 0.0, 1.0) * -dampingSpace;
    } else if (dampingSpace > 0.0) {
        spaceDamp = 1.0 - (1.0 - clamp(abs(rawP - dampingOrigin), 0.0, 1.0)) * dampingSpace;
    }
    float space = max(spacing * max(spaceDamp, 0.0), 0.0001);
    float p = dot(st, rawV * space);
    float ddist = abs(p / space);
    float damp = 1.0;
    if (damping < 0.0) {
        damp = 1.0 - clamp(abs(ddist - dampingOrigin), 0.0, 1.0) * -damping;
    } else if (damping > 0.0) {
        damp = 1.0 - (1.0 - clamp(abs(ddist - dampingOrigin), 0.0, 1.0)) * damping;
    }
    float2 offs = float2(cos(a2), -sin(a2)) * (magnitude * max(damp, 0.0)) / 100.0;
    offs *= sin(p + phase * 6.28318 + time * speed);
    float2 sampleNorm = screenSpace > 0.5 ? st : (float3(st, 1.0) * acLayerToScreen).xy;
    return image.eval((sampleNorm + offs) * screen.zw + screen.xy);
}
